///////////////////////////////////////////////////////////////////////
/// Memory allocators
///////////////////////////////////////////////////////////////////////

class CBlockAllocator
{
public:
	CBlockAllocator(int minSize, int maxSize, int count) 
	{ 
		m_minSize = minSize;
		m_maxSize = ((maxSize + 3) / 4) * 4;
		m_count = count; 
		Init(); 
	}

	~CBlockAllocator()
	{
		free(m_buffer);
	}

	void* Alloc(int size)
	{
		if (m_head == NULL)
			return NULL;

		if (size < m_minSize || size > m_maxSize)
			return NULL;

		void* result = m_head;
		m_head = m_head->next;

		m_used++;
		return result;
	}

	bool Free(void* ptr)
	{
		if (ptr < m_buffer || ptr >= m_buffer + m_maxSize * m_count)
			return false;

		GetBlock(ptr)->next = m_head;
		m_head = GetBlock(ptr);

		m_used--;
		return true;
	}

private:
	struct Block
	{
		Block* next;
	};

	Block* GetBlock (int i)
	{
		return (Block*)(m_buffer + i * m_maxSize);
	}

	Block* GetBlock (void* ptr)
	{
		return (Block*)(ptr);
	}

	void Init()
	{
		m_buffer = (u8*)malloc(m_maxSize * m_count);

		for (int i = 0; i < m_count; i++)
		{
			if (i < m_count - 1)
				GetBlock(i)->next = GetBlock(i + 1);
			else
				GetBlock(i)->next = NULL;
		}

		m_head = GetBlock(m_buffer);
		m_used = 0;
	}

	int m_minSize;
	int m_maxSize;
	int m_count;
	u8* m_buffer;

	Block* m_head;
	int m_used;
};

bool g_allocatorsEnabled = false;

CBlockAllocator	g_allocator1( 4, 32, 4096 );
CBlockAllocator	g_allocator2( 5120, 10240, 128 );

void AllocatorsEnable(bool enable)
{
	g_allocatorsEnabled = enable;
}

void* AllocatorsAlloc(int size)
{
	if (!g_allocatorsEnabled) return NULL;

	void* ptr;
	ptr = g_allocator1.Alloc(size); if (ptr) return ptr;
	ptr = g_allocator2.Alloc(size); if (ptr) return ptr;
	return NULL;
}

bool AllocatorsFree(void* ptr)
{
	if (g_allocator1.Free(ptr)) return true;
	if (g_allocator2.Free(ptr)) return true;
	return false;
}

