void Application::Quit()
{
	/// !!! do not remove curly braces
	{
		CUserProfile profile = __PROFILE();

		/// Sava sound settings 
		__MGR_SOUNDS()->stopAllSounds();

		f32 vol_sfx;
		f32 vol_music;

		vol_sfx		= __MGR_SOUNDS()->getSFxVolume();
		vol_music	= __MGR_SOUNDS()->getMusicVolume();

		profile.Set( "sfx_volume", vol_sfx * 100 );
		profile.Set( "music_volume", vol_music * 100 );		

		/// Skip: 1 - go to about, 2 - exit from about
		int completed;
		profile.Get("GameCompletedState", completed);
		if (completed == 1 || completed == 2)
			profile.Set("GameCompletedState", 3);

		/// Language
		s32 lang = __MGR_STRINGS()->GetLanguage();
		profile.Set( "Language", lang );
	}

	/// Save last loaded achievements
	__ACHIEVEMENTS()->saveAchievementsByProfile( "Player1" );

	// Bug Fixed ['2796673'] - Upon resuming the game after being interrupted the AUT will crash on Gameloft logo.
	//__ACHIEVEMENTS()->release();
	//SAFE_DEL( s_igpInfo );
	//SAFE_DEL( m_accelerometer );
	//SAFE_DEL( m_mediaPlayer );
	//GetDevice()->drop();
}

