// Init string table
void Application::InitializeStrings()
{	
	CUserProfile profile = __PROFILE();

	s32 lang = -1;
	profile.Get( "Language", lang );

	ELanguages profile_lang	= (ELanguages)lang;
	ELanguages device_lang	= __APP()->GetDeviceLanguage();

	if( profile_lang != Language_None )
	{
		__MGR_STRINGS()->SetLanguage( profile_lang );
	}
	else if( device_lang != Language_None )
	{
		__MGR_STRINGS()->SetLanguage( device_lang );
	}
	else
	{
		__MGR_STRINGS()->SetLanguage( Language_None );
	}
}

