void Application::Draw()
{
	IVideoDriver* driver = GetDevice()->getVideoDriver();
	ISceneManager* smgr = GetDevice()->getSceneManager();
	IGUIEnvironment* guienv = GetDevice()->getGUIEnvironment();

	driver->beginScene();
	driver->setClearDepth(10000.0f);
	driver->setClearColor(0xff000000);
	driver->clearBuffers(EFB_COLOR | EFB_DEPTH);

	// 3D scene first
	for(DrawableListIter iter = m_drawableSceneList.begin(); iter != m_drawableSceneList.end(); ++iter)
	{
		(*iter)->draw();
	}

	// HUD second
	for(DrawableListIter iter = m_drawableHUDList.begin(); iter != m_drawableHUDList.end(); ++iter)
	{
		(*iter)->draw();
	}

	// Draw GUI
	driver->beginScene2D();

	__ACHIEVEMENTS()->draw();

	guienv->drawAll();
	PROFILER_DRAW_INFO();
	
	driver->endScene2D();

	driver->endScene();
	//printf("driver->endScene() = %d\n", __IRR_DRIVER()->getPrimitiveCountDrawn());
	driver->swapBuffers(0);
}

u32 frameCount = 0;
u32 frameTime = 0;
float fps = 0;

void Application::_Update(int ticksPerFrame)
{
	++frameCount;

	CTouchPad::UpdateCounters(ticksPerFrame);
	CTouchElement::UpdateElements();

	for(UpdatableListIter iter = m_updatableList.begin(); iter != m_updatableList.end(); ++iter)
	{
		(*iter)->update(ticksPerFrame);
	}
	
	IVideoDriver* driver = GetDevice()->getVideoDriver();
	ISceneManager* smgr = GetDevice()->getSceneManager();
	/** /
	core::stringw str(L"FPS: ");
	str.append(core::stringw(driver->getFPS()));
	str += L" Tris: ";
	str.append(core::stringw(driver->getPrimitiveCountDrawn()));
	m_fpstext->setText(str.c_str());
	/**/
	
	io::IAttributes * attr = smgr->getParameters();
	
	s32 calls = attr->getAttributeAsInt ( "calls" );
	s32 culled = attr->getAttributeAsInt ( "culled" );

	u32 currentTime = os::Timer::getRealTime();
	if (currentTime - frameTime > 1000)
	{
		fps = 1000.0f * (float)frameCount / (currentTime - frameTime);
		frameTime = currentTime;
		frameCount = 0;
	}
	
	wchar_t buf[128];
	swprintf(buf, 128, L"FPS: %4.1f Cull: %d/%d Tris: %d", fps, culled, calls, driver->getPrimitiveCountDrawn());
	m_fpstext->setText(buf);
	m_fpstext->setVisible(false);

	smgr->update(ticksPerFrame);

	FrameEnded(ticksPerFrame);
}

bool Application::UpdateIGP()
{
	if( IsInIGP() )
	{
		if( !igp )
		{
			__MGR_STATES()->sleep();

			createIGP(_launchIGPLang);
		}

#ifdef OS_IPHONE

		setStatusBarOrientation(STATUS_BAR_ORIENTATION_PORTRAIT);

#endif

		bool result = paintIGP();
		if( result )
		{
			releaseIGP();
			
			__IRR_DRIVER()->setViewPort( rect<s32>(0,0,320,480 ) );

			glMatrixMode(GL_MODELVIEW);
			glEnableClientState(GL_VERTEX_ARRAY);
			glEnableClientState(GL_COLOR_ARRAY);		

			NativeStatusBar_UpdateOrientation();

			_launchIGPLang = -1;

			__MGR_STATES()->wakeup();
		}
		return true;
	}

	return false;
}

bool Application::UpdateGLLive()
{
	if( IsInGLLive() )
	{
		if( !glLive )
		{
			__MGR_STATES()->sleep();
			createGLLive(_launchGLLiveLang);
			for( int i=0; i < g_AchievementsListSize; i++ )
			{
				if( CAchievements::GetInstance()->isAchieved( g_AchievementsList[i].name ) )
					NotifyTrophy( i );
			}
		}
		glDisableClientState(GL_COLOR_ARRAY);	// To properly display GLLive loading screens
		bool result = paintGLLive();
		glEnableClientState(GL_COLOR_ARRAY);	// To properly display GLLive loading screens

		if( result )
		{
			releaseGLLive();
			
			glMatrixMode(GL_MODELVIEW);
			glEnableClientState(GL_VERTEX_ARRAY);
			glEnableClientState(GL_COLOR_ARRAY);
			glViewport(0, 0, 320, 480);

			NativeStatusBar_UpdateOrientation();

			_launchGLLiveLang = -1;

			__MGR_STATES()->wakeup();
		}

		return true;
	}

	return false;
}

// /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
// Methods (Game Loop)
// /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
void Application::Update()
{
	PROFILER_SCOPE(app_update);
	PROFILER_GATHER_INFO();

	static u32 lastTime = os::Timer::getTime();
	u32 currentTime = os::Timer::getTime();
	u32 deltaTime = currentTime - lastTime;

	lastTime = currentTime;
	CLAMP(deltaTime, 1, 100);

	
	UpdateOrientationChanges();
#ifdef OS_IPHONE
	if( UpdateIGP() )
		return;
		
	if( UpdateGLLive() )
		return;
#endif
	_Update(deltaTime);
	Draw();
	CXPlayerManager::GetInstance()->Update();
}


