// /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
// Methods (IEventReceiver impl.)
// /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
bool Application::OnEvent(const SEvent& ev)
{
	bool handled = false;

	for(EventReceiverListIter iter = m_eventReceivers.begin(); iter != m_eventReceivers.end(); ++iter)
	{
		handled |= (*iter)->OnEvent(ev);
	}

	if(ev.EventType == EET_KEY_INPUT_EVENT)
	{
		GetEventManager()->raise(
			EvKeyboard(
				ev.KeyInput.Key, ev.KeyInput.Char, ev.KeyInput.PressedDown,
				ev.KeyInput.Shift, ev.KeyInput.Control, false
				)
			);

		return true;
	}
	else if(ev.EventType == EET_MOUSE_INPUT_EVENT)
	{
		switch(ev.MouseInput.Event)
		{
		case EMIE_MOUSE_MOVED:
			GetEventManager()->raise(EvMouseMove(ev.MouseInput.X, ev.MouseInput.Y));
			break;

		case EMIE_MOUSE_WHEEL:
			GetEventManager()->raise(EvMouseWheel((int)ev.MouseInput.Wheel));
			break;

		case EMIE_LMOUSE_LEFT_UP:
		case EMIE_LMOUSE_PRESSED_DOWN:
			GetEventManager()->raise(EvMouseButton(EvMouseButton::LEFT, ev.MouseInput.Event == EMIE_LMOUSE_PRESSED_DOWN, ev.MouseInput.X, ev.MouseInput.Y));
			break;
		
		case EMIE_MMOUSE_LEFT_UP:
			CGameConfig::RenderToTexture = !CGameConfig::RenderToTexture;
		case EMIE_MMOUSE_PRESSED_DOWN:
			GetEventManager()->raise(EvMouseButton(EvMouseButton::MIDDLE, ev.MouseInput.Event == EMIE_MMOUSE_PRESSED_DOWN, ev.MouseInput.X, ev.MouseInput.Y));
			break;
		
		case EMIE_RMOUSE_LEFT_UP:
		case EMIE_RMOUSE_PRESSED_DOWN:
			GetEventManager()->raise(EvMouseButton(EvMouseButton::RIGHT, ev.MouseInput.Event == EMIE_RMOUSE_PRESSED_DOWN, ev.MouseInput.X, ev.MouseInput.Y));
			break;
		}

		return true;
	}

	return handled;
}

