ELanguages Application::GetDeviceLanguage()
{
	char buffer[16] = { 0 };

#ifdef OS_IPHONE

     DeviceLanguage(buffer); 

#else

	sprintf(buffer,"ch");

#endif

	 ELanguages lang = Language_None;

     if(strcmp(buffer, "en") == 0)
          lang = Language_English;
     else if(strcmp(buffer, "de") == 0)
          lang = Language_Deutsch;
     else if(strcmp(buffer, "fr") == 0)
          lang = Language_French;
     else if(strcmp(buffer, "it") == 0)
          lang = Language_Italian;
     else if(strcmp(buffer, "es") == 0)
		 lang = Language_Spanish;
     else if(strcmp(buffer, "ja") == 0)
          lang = Language_Japanese;
//	 else if(strcmp(buffer, "zh-Hans") == 0)
//		lang = Language_SimplifiedChinese;

	return lang;
}

