void Application::setFilePaths( const char* root, const char* resources, const char* save_file )
{
#if defined(OS_IPHONE) || defined(OS_LINUX)
	strcpy( m_rootPath, root );
	strcpy( m_resourcesPath, resources );
	strcpy( m_savefilesPath, save_file );
#else
	strcpy_s( m_rootPath, PATH_LEN-1, root );
	strcpy_s( m_resourcesPath, PATH_LEN-1, resources );
	strcpy_s( m_savefilesPath, PATH_LEN-1, save_file );
#endif
	
}

const char*	Application::getFileRootPath() const
{
	return m_rootPath;
}

const char*	Application::getFileResPath()	const
{
	return m_resourcesPath;
}

const char*	Application::getFileSavePath()	const
{
	return m_savefilesPath;
}


