//////////////////////////////////////////////////////////////////////////
/// Orientations
//////////////////////////////////////////////////////////////////////////

void Application::UpdateOrientationChanges()
{
#ifdef OS_IPHONE

	//first initialization

	if ( !isDeviceSetted ) 
		return;

	static bool once = false;
	if ( !once ) 
	{
		if( isDeviceIPod)
		{
			CTouchPad::s_currentDeviceOrientation = EOO_270;
		} 
		else 
		{
			CTouchPad::s_currentDeviceOrientation = EOO_90;
		}
		once = true;
	}

	if ( !m_deviceOrientationLocked && m_profileReadOrientations &&
		( ( !CPlayfield::GetInstance()->IsLevelLoaded() ) || 
		  ( CPlayfield::GetInstance()->IsLevelLoaded() && 
		    CPlayfield::GetInstance()->GetPlayState() == CPlayfield::PS_IGM ) ) ) 		
	{		
		if ( CTouchPad::s_currentTiltX > 20 && CTouchPad::s_currentDeviceOrientation == EOO_270 )
		{
			CTouchPad::s_currentDeviceOrientation = EOO_90;
			//NativeStatusBar_UpdateOrientation();
		} 
		else if ( CTouchPad::s_currentTiltX < -20 && CTouchPad::s_currentDeviceOrientation == EOO_90 )
		{
			CTouchPad::s_currentDeviceOrientation = EOO_270;
			//NativeStatusBar_UpdateOrientation();
		}
	}

	if( __IRR_DEVICE()->getVideoDriver()->getOrientation3D() != CTouchPad::s_currentDeviceOrientation )
	{
		if ( CTouchPad::s_currentDeviceOrientation == EOO_270 )
		{
			m_irrDevice->getVideoDriver()->setOrientation3D( EOO_270 );
			m_irrDevice->getVideoDriver()->setOrthoOrientation( EOO_270 );
		}
		else
		{
			m_irrDevice->getVideoDriver()->setOrientation3D( EOO_90 );
			m_irrDevice->getVideoDriver()->setOrthoOrientation( EOO_90 );
		}

		NativeStatusBar_UpdateOrientation();
	}
#else
	static bool once = false; 
	//called only first time in win32
	//if ( !once ) 
	{
		m_irrDevice->getVideoDriver()->setOrientation3D( CTouchPad::s_currentDeviceOrientation );
		m_irrDevice->getVideoDriver()->setOrthoOrientation( CTouchPad::s_currentDeviceOrientation );
		//CTouchPad::s_currentDeviceOrientation = EOO_0;
		once = true;
	}
#endif
}

void Application::NativeStatusBar_UpdateOrientation()
{
	#ifdef OS_IPHONE
		native_StatusBar_UpdateOrientation();
	#endif //OS_IPHONE
}


void Application::ShowStatusBar( bool visible )
{
	NativeStatusBar_UpdateOrientation();

#ifdef OS_IPHONE 
	showStatusBar( visible );
#endif 
}

